query BatchSubmission($id: ID!, $version: Int!) {
  changeBatch(id: $id) {
    id
    submittedVersion
    submission(version: $version)
  }
}

mutation ChangeBatchChanges($input: ChangeBatchChangesInput!) {
  changeBatchChanges(input: $input) {
    items {
      key
      status
      result
      error
    }
    instructions {
      code
      itemKey
      actor
      required
      message
      call
      taskId
      url
    }
  }
}

query CreativeRecords($kind: String, $after: String, $limit: Int) {
  creativeRecordViews(kind: $kind, after: $after, limit: $limit)
}

query Exploration($slug: String!) {
  exploration(slug: $slug) {
    slug
    title
    revision
    state
    lastChange
    picture {
      nodes {
        key
        type
        title
        step
        url
        proposedIn
      }
      edges {
        from
        to
        label
      }
      steps {
        key
        count
        truncated
        error
      }
      truncated
    }
  }
}

query Explorations {
  explorations {
    slug
    title
    revision
    start
  }
}

mutation FreezeCreativeInputs($input: FreezeCreativeInputsAtAddressInput!) {
  freezeCreativeInputsAtAddress(input: $input)
}

mutation MutateExploration($input: MutateExplorationInput!) {
  mutateExploration(input: $input) {
    slug
    title
    revision
    lastChange
    picture {
      nodes {
        key
        type
        title
        step
        url
        proposedIn
      }
      edges {
        from
        to
        label
      }
      steps {
        key
        count
        truncated
        error
      }
      truncated
    }
  }
}

mutation MutateShare($input: MutateShareInput!) {
  mutateShare(input: $input) {
    slug
    title
    revision
    archived
    organization
    graph
    roots
    hidden
    view {
      nodes {
        address
        title
        summary
      }
      edges {
        address
      }
      incomplete
    }
  }
}

query Ontology {
  ontology {
    root
    nodeTypes {
      name
      description
    }
    relationshipTypes {
      name
      description
      from
      to
    }
    staging
  }
}

query OntoSettings {
  settings {
    stewardApproval
    updatedAt
    updatedBy
  }
}

mutation RemoveStagedChanges($input: RemoveStagedChangesInput!) {
  removeStagedChanges(input: $input) {
    id
    state
    counts
    anchors
    validation
  }
}

mutation ReviseBatch($input: ReviseBatchInput!) {
  reviseBatch(input: $input) {
    id
    submittedVersion
    title
    state
    counts
    reviewBy
    reviewUrl
  }
}

mutation SaveSettings($input: SaveSettingsInput!) {
  saveSettings(input: $input) {
    stewardApproval
    updatedAt
    updatedBy
  }
}

query Share($slug: String!) {
  share(slug: $slug) {
    slug
    title
    revision
    archived
    organization
    graph
    roots
    hidden
    view {
      nodes {
        address
        title
        summary
      }
      edges {
        address
      }
